mapper.update:
UPDATE growth_evidence
SET
    valid_to = COALESCE(valid_to, #{invalidatedAt}),
    update_time = NOW()
WHERE user_id = #{userId}
  AND source_module = #{sourceModule}
  AND source_type = #{sourceType}
  AND source_id = #{sourceId}
  AND evidence_type = #{evidenceType}
  AND projector_version = #{projectorVersion}
  AND valid_to IS NULL
